nui 1
// #1509 C1: frozen independently before evaluation
const width: number = 40
const radius: number = 30
const allowance: number = 4
profile Draft
profile Cut
style Ink {
 width: 2px,
 color: #123456,
}
style SeamInk {
 width: 2px,
 color: #ab5412,
 for @Cut {
  visible: false,
 }
}
style MarkInk {
 width: 2px,
 color: #127a45,
 for @Cut {
  visible: false,
 }
}
group Piece {
 point Origin = coordinate(x: 0, y: 0)
 line Straight = segment(start: (0, 0), end: (@width, 0), visible: false)
 arc Bend = arc(center: (@width, @radius), radius: @radius, start: 270, end: 360, direction: counterclockwise, visible: false)
 line Contour [Ink] = join(paths: [@Straight, @Bend], closed: false)
 line Allowance [SeamInk] = offset(sources: [@Contour], distance: @allowance, side: right, closed: false)
 point Station1 = onLine(from: @Contour.start, ratio: 0.64, visible: false)
 point Tip1 = tangentOffset(line: @Contour, base: @Station1, angle: -90, distance: 6, visible: false)
 line Mark1 [MarkInk] = segment(start: @Station1, end: @Tip1, visible: true)
}
group Control {
 line Calibration [Ink] = segment(start: (0, -15), end: (100, -15))
 line Sibling [Ink] = segment(start: (0, -10), end: (3, -6))
}
group Unselected {
 line Outside = segment(start: (9000, 9000), end: (9100, 9000))
}
layout Pattern {
 place @Piece(origin: @Piece::Origin, at: (0, 0), scale: 1, angle: 0, mirror: false)
 place @Control(at: (0, 0))
}
svg Vector(layout: @Pattern, profile: @Draft, margin: 3)
print Paper(layout: @Pattern, profile: @Draft, paper: a4, orientation: portrait, overlap: 10)

